# Probe: what else can the site read from 1C?
#
# READ-ONLY. Nothing is written, nothing is posted.
#
# Four questions, each independent -- a failure in one block does not stop the
# others, because a missing object in this configuration throws a bare
# NullReferenceException and that is exactly what we are testing for.
#
#   1. Counterparty ADDRESS and PHONE. The site geocodes clients from
#      Counterparty.address, and only 375 of 3689 cards have coordinates --
#      which cripples the driver map, route planning and delivery zones.
#      The sync currently reads name/code only.
#   2. BARCODES. Product.barcodes exists and is empty; the mobile scanner
#      falls back to our own QR. Nobody has ever checked whether 1C has them.
#   3. PKO -> realization link (Sdelka). PaymentAllocation.profitAmount is
#      always 0 because the payment does not know which invoice it closes,
#      so commission on collected PROFIT is impossible today.
#   4. Incoming goods (PostuplenieTovarovUslug). The purchase channel exists
#      on the server side but has no producer -- no supplier debt, no
#      purchase prices, cost of sales comes from one register only.
#
# Run in 32-bit PowerShell (the COM connector is 32-bit):
#   C:\Windows\SysWOW64\WindowsPowerShell\v1.0\powershell.exe -ep bypass -f \\tsclient\Downloads\probe-coverage.ps1 > \\tsclient\Downloads\probe-out.txt 2>&1
#
# ASCII-only source: PowerShell 5 reads .ps1 in the OEM codepage, so Cyrillic
# in a literal is mangled before the parser sees it. Every Russian identifier
# below is built from character codes.

[CmdletBinding()]
param(
    [string] $ConfigPath = "C:\Users\fedyshyn\budvik-agent\ps\config.json",
    [int] $Months = 12
)

$ErrorActionPreference = "Stop"

function C([int[]] $codes) { -join ($codes | ForEach-Object { [char]$_ }) }

# The agent has moved between layouts (C:\budvik-agent and the user profile,
# with and without a ps\ subfolder), so the config is searched rather than
# assumed. A wrong guess costs a whole round trip through the RDP session.
if (-not (Test-Path $ConfigPath)) {
    $candidates = @(
        "C:\Users\fedyshyn\budvik-agent\ps\config.json",
        "C:\Users\fedyshyn\budvik-agent\config.json",
        "C:\budvik-agent\ps\config.json",
        "C:\budvik-agent\config.json"
    )
    $here = $PSScriptRoot
    if (-not $here) { $here = Split-Path -Parent $MyInvocation.MyCommand.Path }
    if ($here) { $candidates += (Join-Path $here "config.json") }

    $ConfigPath = $null
    foreach ($cand in $candidates) {
        if (Test-Path $cand) { $ConfigPath = $cand; break }
    }

    # Last resort: sweep the agent folder wherever it lives.
    if (-not $ConfigPath) {
        foreach ($root in @("C:\Users\fedyshyn\budvik-agent", "C:\budvik-agent", "C:\Users\fedyshyn")) {
            if (-not (Test-Path $root)) { continue }
            $hit = Get-ChildItem -Path $root -Filter "config.json" -Recurse -ErrorAction SilentlyContinue |
                   Select-Object -First 1
            if ($hit) { $ConfigPath = $hit.FullName; break }
        }
    }

    if (-not $ConfigPath) {
        throw "config.json not found anywhere under budvik-agent. Pass -ConfigPath <full path>"
    }
    Write-Host "using config: $ConfigPath"
}

$config = [IO.File]::ReadAllText($ConfigPath, [Text.Encoding]::UTF8) | ConvertFrom-Json

$conn = New-Object -ComObject "V82.COMConnector"
$cs = "Srvr=""{0}"";Ref=""{1}"";Usr=""{2}"";Pwd=""{3}"";" -f `
    $config.oneC.server, $config.oneC.base, $config.oneC.user, $config.oneC.password
$ib = $conn.Connect($cs)
Write-Host "CONNECTED to $($config.oneC.base)"
Write-Host ""

$since = (Get-Date).AddMonths(-$Months)

# Runs a query with no parameters and returns the selection, or $null.
# Deliberately NOT used for parameterised queries: a function that builds one
# and returns it comes back null on this build (known quirk).
function RunQuery([string] $text) {
    $q = $ib.NewObject("Query")
    $q.Text = $text
    $rs = $q.Execute()
    if ($null -eq $rs) { return $null }
    return $rs.Choose()
}

function Str($v) { if ($null -eq $v) { return "" } else { return [string]$v } }

