# ============================================================
Write-Host "=== 1. COUNTERPARTY: address and phone ==="
# Each candidate attribute is probed on its own: referencing a field that does
# not exist is exactly how we learn it does not exist (there is no metadata
# access over COM on this build).
$found = @()
foreach ($cand in $CP_CANDIDATES) {
    $text = $CP_ATTR_TPL -replace "@FIELD@", $cand
    try {
        $r = RunQuery $text
        if ($null -eq $r) { Write-Host ("  {0}: query returned null" -f $cand); continue }
        if ($r.Next()) {
            $val = Str $r.Get(2)
            $shown = if ($val.Length -gt 60) { $val.Substring(0, 60) + "..." } else { $val }
            Write-Host ("  {0}: EXISTS, sample = '{1}'" -f $cand, $shown)
            $found += $cand
        } else {
            Write-Host ("  {0}: EXISTS but catalogue is empty" -f $cand)
        }
    } catch {
        Write-Host ("  {0}: no such attribute" -f $cand)
    }
}
Write-Host ("  -> usable attributes: {0}" -f $(if ($found.Count) { $found -join ", " } else { "NONE" }))
Write-Host ""

# How full is the attribute that exists? An address on 3 cards out of 3689 is
# not a data source, it is noise -- and that decides whether to wire it up.
foreach ($cand in $found) {
    try {
        $text = $CP_FILL_TPL -replace "@FIELD@", $cand
        $r = RunQuery $text
        if ($r -and $r.Next()) {
            # Get(0) = total, Get(1) = filled -- keep the order straight.
            Write-Host ("  {0}: filled on {1} of {2} counterparties" -f $cand, $r.Get(1), $r.Get(0))
        }
    } catch {
        Write-Host ("  {0}: could not count fill rate -- {1}" -f $cand, $_.Exception.Message)
    }
}
Write-Host ""

Write-Host "=== 2. CONTACT INFORMATION register ==="
try {
    $r = RunQuery $CI_COUNT
    if ($r -and $r.Next()) {
        Write-Host ("  register exists: {0} rows for {1} objects" -f $r.Get(1), $r.Get(0))
    }
    $r = RunQuery $CI_SAMPLE
    $n = 0
    while ($r -and $r.Next() -and $n -lt 5) {
        Write-Host ("    type='{0}' value='{1}'" -f (Str $r.Get(1)), (Str $r.Get(2)))
        $n++
    }
} catch {
    Write-Host ("  no such register -- " + $_.Exception.Message)
}
Write-Host ""

Write-Host "=== 3. DELIVERY ADDRESS on realizations ==="
# Already read for route-sheet stops, so if the catalogue has nothing this is
# the cheapest fallback: the address the goods actually went to.
try {
    $r = RunQuery $ADDR_REAL
    if ($r -and $r.Next()) { Write-Host ("  realizations with a delivery address: {0}" -f $r.Get(0)) }
} catch {
    Write-Host ("  could not count -- " + $_.Exception.Message)
}
Write-Host ""

# ============================================================
Write-Host "=== 4. BARCODES ==="
$bcFound = $false
foreach ($pair in $BC_CANDIDATES) {
    try {
        $r = RunQuery $pair.Query
        if ($null -eq $r) { Write-Host ("  {0}: null" -f $pair.Name); continue }
        $n = 0
        while ($r.Next() -and $n -lt 3) {
            Write-Host ("  {0}: '{1}'" -f $pair.Name, (Str $r.Get(0)))
            $n++
            $bcFound = $true
        }
        if ($n -eq 0) { Write-Host ("  {0}: exists but EMPTY" -f $pair.Name) }
    } catch {
        Write-Host ("  {0}: absent" -f $pair.Name)
    }
}
if (-not $bcFound) { Write-Host "  -> no barcodes in this base" }
Write-Host ""

# ============================================================
Write-Host "=== 5. PKO -> what does Sdelka point at? ==="
# Inline on purpose: a parameterised query built inside a function returns
# null on this build.
try {
    $q = $ib.NewObject("Query")
    $q.Text = $PKO_SDELKA
    $q.SetParameter($PARAM_FROM, $since)
    $rs = $q.Execute()
    if ($null -eq $rs) { throw "Execute returned null" }
    $r = $rs.Choose()
    $kinds = @{}
    $total = 0
    while ($r.Next()) {
        $k = Str $r.Get(0)
        if (-not $kinds.ContainsKey($k)) { $kinds[$k] = 0 }
        $kinds[$k] = $kinds[$k] + 1
        $total++
    }
    Write-Host ("  payment rows examined: {0}" -f $total)
    foreach ($k in $kinds.Keys) {
        Write-Host ("    {0}: {1}" -f $k, $kinds[$k])
    }
} catch {
    Write-Host ("  FAILED -- " + $_.Exception.Message)
}
Write-Host ""

# ============================================================
Write-Host "=== 6. INCOMING GOODS (supply side) ==="
try {
    $q = $ib.NewObject("Query")
    $q.Text = $POS_COUNT
    $q.SetParameter($PARAM_FROM, $since)
    $rs = $q.Execute()
    if ($null -eq $rs) { throw "Execute returned null" }
    $r = $rs.Choose()
    if ($r.Next()) {
        Write-Host ("  posted receipts in last {0} months: {1}, total {2}" -f $Months, $r.Get(0), $r.Get(1))
    }

    $q = $ib.NewObject("Query")
    $q.Text = $POS_SAMPLE
    $q.SetParameter($PARAM_FROM, $since)
    $rs = $q.Execute()
    $r = $rs.Choose()
    while ($r.Next()) {
        Write-Host ("    #{0} {1:yyyy-MM-dd} {2} = {3}" -f (Str $r.Get(1)), $r.Get(2), (Str $r.Get(3)), $r.Get(4))
    }
} catch {
    Write-Host ("  FAILED -- " + $_.Exception.Message)
}
Write-Host ""
Write-Host "=== DONE ==="
